input.query:
SELECT MIN(accident_date), MAX(accident_date), COUNT(*) FROM claim WHERE peril='WINDSCREEN' AND EXTRACT(year FROM accident_date)=2024;
SELECT COUNT(*) FROM claim_txn t JOIN claim c USING(claim_id) WHERE c.peril='WINDSCREEN' AND t.txn_type='RECOVERY';
SELECT txn_type, cost_type, MIN(amount), MAX(amount), COUNT(*) FROM claim_txn GROUP BY 1,2;

SELECT SUM(t.amount) AS incurred_all, SUM(CASE WHEN t.cost_type='INDEMNITY' THEN t.amount ELSE 0 END) AS indemnity, SUM(CASE WHEN t.cost_type='ALAE' THEN t.amount ELSE 0 END) AS alae, COUNT(DISTINCT c.claim_id) AS n_claims
FROM claim c JOIN claim_txn t USING(claim_id)
WHERE c.peril='WINDSCREEN' AND EXTRACT(year FROM c.accident_date)=2024;
SELECT SUM(written_premium) AS wp, SUM(exposure_units) AS exp FROM premium_txn p JOIN policy_term t USING(term_id) WHERE EXTRACT(year FROM t.inception_date)=2024;
